test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

}

source src_base
{
	type = mysql

}

source src_1 : src_base
{
	sql_query = SELECT id, attr1, mva1, mva2, str1, str2, text FROM test_table WHERE idx = 'i1';

	sql_attr_multi = uint mva1 from field
	sql_attr_multi = uint mva2 from field
	sql_attr_string = str1
	sql_attr_string = str2
	sql_attr_uint	= attr1
}

source src_2 : src_1
{
	sql_query = SELECT id, attr1, mva1, mva2, str1, str2, text FROM test_table WHERE idx = 'i2';
}

index i1
{
	source			= src_1
	path			= /i1

}

index i2
{
	source			= src_2
	path			= /i2

}

index ll
{
	type			= distributed
	local = i1
	local = i2
}

index ld
{
	type			= distributed
	local			= i1
	agent			= :i2
	local = i2
}

index dd
{
	type			= distributed
	agent			= :i1
	agent			= :i2
}

index mva64_1
{
	type = rt
	path = /mva64_1
	rt_field = title
	rt_attr_multi_64 = m
}

index mva64_2 : mva64_1
{
	path = /mva64_2
}

queries.sphinxql:
select * from i1 where match ('some');
select attr1, groupby() g from i1 where match ('some') group by mva1 order by g asc;
select attr1, groupby() g from i1 where match ('some') group by mva2 order by g asc;
select attr1, groupby() g from ld where match ('some') group by mva1 order by g asc;
select attr1, groupby() g from ld where match ('some') group by mva2 order by g asc;
select attr1, groupby() g from dd where match ('some') group by mva1 order by g asc;
select attr1, groupby() g from dd where match ('some') group by mva2 order by g asc;
select mva1, least(mva1), greatest(mva1) from i1;

select groupby() from i1 group by str1 order by str1 asc;
select groupby() from i1 group by str1 order by str1 desc;

select groupby() g, count(*) c from i1 group by mva1 order by g asc;
select groupby() g, count(*) c from i1,i2 group by mva1 order by g asc;
select groupby() g, count(*) c from i1,i2 group by mva1 having g in (12,101) order by g asc;

select groupby() g, count(*) c from i1 group by mva2 having c > 1 order by g asc;
select groupby() g, count(distinct id) c from i1,i2 group by mva1 order by g asc;

insert into mva64_1 (id,m) values (1,(5000000000,6000000000));
insert into mva64_2 (id,m) values (2,(5000000000,7000000000));
select groupby() g, count(*) c from mva64_1,mva64_2 group by m order by g asc;
select count(*) from i1 group by missing_attribute;
